pub async fn channel_language(pool: Option<&sqlx::PgPool>, broadcaster_id: &str) -> TextLanguage {
    match pool {
        Some(pool) => tb_db::guild_membership::twitch_language(pool, broadcaster_id).await,
        None => TextLanguage::German,
    }
}
